<?php /** @var array $x @var array $names */ $c = $x['c']; $r = $x['r']; $ar = locale() === 'ar'; require __DIR__ . '/_tabs.php'; require __DIR__ . '/_summary.php'; $edit = can('icaap.manage') && !$locked;
$lc = ['low' => 'ok', 'medium' => 'warn', 'high' => 'danger', 'critical' => 'danger']; ?>
<form method="post" action="<?= e(url('icaap/' . $c['id'] . '/risks')) ?>" novalidate><?= csrf_field() ?>
<section class="card"><h2><?= e(t('icaap.materiality')) ?></h2><p class="muted"><?= e(t('icaap.materiality_rule')) ?></p>
<div class="table-wrap"><table class="data icaap-grid"><thead><tr><th><?= e(t('icaap.risk')) ?></th><th><?= e(t('icaap.impact')) ?></th><th><?= e(t('icaap.likelihood')) ?></th><th><?= e(t('icaap.score')) ?></th><th><?= e(t('icaap.result')) ?></th><th><?= e(t('icaap.justification')) ?></th><th><?= e(t('icaap.change_note')) ?></th></tr></thead><tbody>
<?php foreach ($x['risks'] as $q): $k = $q['risk_key']; $m = $r['materiality'][$k]; ?><tr><td><strong><?= e($ar ? $names[$k][2] : $names[$k][3]) ?></strong><br><span class="muted small"><?= e(t('enum.rmsec.' . $q['section'])) ?></span></td>
<td><select name="impact[<?= e($k) ?>]" aria-label="<?= e(t('icaap.impact')) ?>"<?= $edit ? '' : ' disabled' ?>><option value="">—</option><?php for ($i = 1; $i <= 5; $i++): ?><option value="<?= $i ?>"<?= (int)$q['impact'] === $i ? ' selected' : '' ?>><?= $i ?></option><?php endfor; ?></select><?= field_error('impact_' . $k) ?></td>
<td><select name="likelihood[<?= e($k) ?>]" aria-label="<?= e(t('icaap.likelihood')) ?>"<?= $edit ? '' : ' disabled' ?>><option value="">—</option><?php for ($i = 1; $i <= 5; $i++): ?><option value="<?= $i ?>"<?= (int)$q['likelihood'] === $i ? ' selected' : '' ?>><?= $i ?></option><?php endfor; ?></select><?= field_error('likelihood_' . $k) ?></td>
<td class="num"><?= $m['score'] ?? '—' ?><?= $m['level'] ? ' <span class="badge ' . $lc[$m['level']] . '">' . e(t('enum.iclevel.' . $m['level'])) . '</span>' : '' ?></td>
<td><?= $m['material'] === null ? '—' : ($m['material'] ? '<span class="badge danger">' . e(t('icaap.material')) . '</span>' : '<span class="badge">' . e(t('icaap.not_material')) . '</span>') ?></td>
<td><textarea name="justification[<?= e($k) ?>]" rows="2" aria-label="<?= e(t('icaap.justification')) ?>"<?= $edit ? '' : ' readonly' ?>><?= e(old('justification', [])[$k] ?? $q['justification'] ?? '') ?></textarea><?= field_error('justification_' . $k) ?></td>
<td><input type="text" name="change_note[<?= e($k) ?>]" value="<?= e($q['change_note'] ?? '') ?>" aria-label="<?= e(t('icaap.change_note')) ?>"<?= $edit ? '' : ' readonly' ?>></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><h2><?= e(t('icaap.pillar2')) ?></h2><p class="muted"><?= e(t('icaap.pillar2_hint')) ?></p>
<div class="table-wrap"><table class="data icaap-grid"><thead><tr><th><?= e(t('icaap.risk')) ?></th><th><?= e(t('icaap.method')) ?></th><th class="num"><?= e(t('icaap.capital')) ?></th></tr></thead><tbody>
<?php foreach ($x['risks'] as $q): $k = $q['risk_key']; $mat = $r['materiality'][$k]['material'] ?? false; ?><tr<?= $mat ? '' : ' class="muted"' ?>><td><?= e($ar ? $names[$k][2] : $names[$k][3]) ?><?= $mat ? ' <span class="badge danger">' . e(t('icaap.material')) . '</span>' : '' ?></td>
<td><textarea name="method[<?= e($k) ?>]" rows="2" aria-label="<?= e(t('icaap.method')) ?>"<?= $edit ? '' : ' readonly' ?>><?= e($q['method'] ?? '') ?></textarea><?= field_error('method_' . $k) ?></td>
<td><input type="text" name="capital[<?= e($k) ?>]" value="<?= e($q['capital'] !== null ? \App\Core\Money::plain($q['capital']) : '') ?>" dir="ltr" inputmode="decimal" aria-label="<?= e(t('icaap.capital')) ?>"<?= $edit ? '' : ' readonly' ?>><?= field_error('capital_' . $k) ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="form-grid"><?= ff('text', 'mgmt_buffer', 'icaap.mgmt_buffer', $c['mgmt_buffer'] !== null ? rtrim(rtrim(number_format((float)$c['mgmt_buffer'] * 100, 4, '.', ''), '0'), '.') : '', ['dir' => 'ltr', 'hint' => t('icaap.mgmt_buffer_hint')]) ?>
<?= ff('text', 'aggregation', 'icaap.aggregation', $c['aggregation'] ?? '', ['hint' => t('icaap.aggregation_hint')]) ?></div>
<table class="data"><tbody><tr><td><?= e(t('icaap.p1')) ?></td><td class="num"><?= $r['p1'] === null ? '—' : e(number_format($r['p1'], 0)) ?></td></tr><tr><td><?= e(t('icaap.p2')) ?></td><td class="num"><?= e(number_format($r['p2'], 0)) ?></td></tr>
<tr><td><?= e(t('icaap.mgmt_buffer')) ?></td><td class="num"><?= $r['buffer'] === null ? '—' : e(number_format($r['buffer'], 0)) ?></td></tr><tr><th><?= e(t('icaap.required')) ?></th><th class="num"><?= $r['required'] === null ? '—' : e(number_format($r['required'], 0)) ?></th></tr>
<tr><td><?= e(t('icaap.available')) ?></td><td class="num"><?= $r['available'] === null ? '—' : e(number_format($r['available'], 0)) ?></td></tr><tr><th><?= e(t('icaap.margin')) ?></th><th class="num"><?= $r['margin'] === null ? '—' : e(number_format($r['margin'], 0)) ?><?= $r['margin'] !== null && $r['margin'] < 0 ? ' <span class="badge danger">' . e(t('icaap.deficit')) . '</span>' : '' ?></th></tr></tbody></table>
<?php if ($edit): ?><div class="actions"><button class="btn" type="submit"><?= e(t('common.save')) ?></button></div><?php endif; ?></section></form>
